rackByPatientId($index, patient)) {\r\n                <tr>\r\n                  <td>{{ patient.id }}</td>\r\n                  <td>{{ patient.firstName }}</td>\r\n                  <td>{{ patient.lastName }}</td>\r\n                  <td>{{ patient.fiscalCode || '-' }}</td>\r\n                  <td>{{ (patient.birthDate | date:'dd/MM/yyyy') || '-' }}</td>\r\n                  <td>{{ patient.gender || '-' }}</td>\r\n                  <td class=\"text-center\">\r\n                    <div class=\"btn-group btn-group-sm\" role=\"group\">\r\n                      <button class=\"btn btn-outline-primary\" type=\"button\" (click)=\"onEdit(patient)\" title=\"Modifica\" aria-label=\"Modifica\">\r\n                        <i class=\"fas fa-edit\"></i>\r\n                      </button>\r\n                      <button class=\"btn btn-outline-danger\" type=\"button\" (click)=\"onDelete(patient)\" title=\"Elimina\" aria-label=\"Elimina\">\r\n                        <i class=\"fas fa-trash\"></i>\r\n                      </button>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              } @empty {\r\n                <tr>\r\n                  <td colspan=\"7\" class=\"text-center py-4 text-muted\">\r\n                    <i class=\"fas fa-search fa-2x mb-2 d-block opacity-50\"></i>\r\n                    Nessun paziente trovato\r\n                  </td>\r\n                </tr>\r\n              }\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <!-- Pagination -->\r\n        @if (totalPages > 1) {\r\n          <nav class=\"px-3 py-2 border-top\" aria-label=\"Paginazione pazienti\">\r\n            <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2\">\r\n              <div class=\"small text-muted\">\r\n                Mostrando {{ (currentPage - 1) * pageSize + 1 }} - {{ Math.min(currentPage * pageSize, totalItems) }} di {{ totalItems }} pazienti\r\n              </div>\r\n              <ul class=\"pagination pagination-sm mb-0\">\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === 1\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(1)\" [disabled]=\"currentPage === 1\" aria-label=\"Prima pagina\">\r\n                    <i class=\"fas fa-angle-double-left\"></i>\r\n                  </button>\r\n                </li>\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === 1\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(currentPage - 1)\" [disabled]=\"currentPage === 1\" aria-label=\"Pagina precedente\">\r\n                    <i class=\"fas fa-angle-left\"></i>\r\n                  </button>\r\n                </li>\r\n                @for (page of pages; track page) {\r\n                  <li class=\"page-item\" [class.active]=\"page === currentPage\">\r\n                    <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(page)\">{{ page }}</button>\r\n                  </li>\r\n                }\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === totalPages\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(currentPage + 1)\" [disabled]=\"currentPage === totalPages\" aria-label=\"Pagina successiva\">\r\n                    <i class=\"fas fa-angle-right\"></i>\r\n                  </button>\r\n                </li>\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === totalPages\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(totalPages)\" [disabled]=\"currentPage === totalPages\" aria-label=\"Ultima pagina\">\r\n                    <i class=\"fas fa-angle-double-right\"></i>\r\n                  </button>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </nav>\r\n        }\r\n      }\r\n    </div>\r\n  </div>\r\n</div>\r\n",
      styles: [".sortable-table th.sortable{cursor:pointer;-webkit-user-select:none;user-select:none;transition:background-color .15s ease;white-space:nowrap}.sortable-table th.sortable:hover{background-color:#b6d4fe!important}.sortable-table th.sortable.sorted{background-color:#9ec5fe!important;color:#0d6efd}.sortable-table th.sortable i.fa-sort{color:#6ea8fe;margin-left:.25rem;font-size:.75rem;opacity:.8}.sortable-table th.sortable.sorted i.fa-sort-up,.sortable-table th.sortable.sorted i.fa-sort-down{color:#0d6efd;opacity:1}.sortable-table th.sortable:not(.sorted) i.fa-sort-up,.sortable-table th.sortable:not(.sorted) i.fa-sort-down{display:none}.table td,.table th{vertical-align:middle}.btn-group-sm .btn{padding:.25rem .5rem;font-size:.8rem}.pagination .page-link{color:#0d6efd;border-color:#dee2e6;padding:.25rem .5rem;font-size:.8rem}.pagination .page-link:hover{background-color:#e9ecef;border-color:#dee2e6;color:#0a58ca}.pagination .page-item.active .page-link{background-color:#0d6efd;border-color:#0d6efd;color:#fff}.pagination .page-item.disabled .page-link{color:#6c757d;pointer-events:none;background-color:#fff;border-color:#dee2e6}.card{border-radius:.75rem;border:none;box-shadow:0 .125rem .25rem #00000013}.card-header{border-radius:.75rem .75rem 0 0!important}.form-label{font-size:.75rem;color:#6c757d}.form-control,.form-select{font-size:.875rem}@media (max-width: 768px){.pagination{flex-wrap:wrap;justify-content:center}.pagination .page-link{padding:.2rem .4rem;font-size:.75rem}.btn-group-sm .btn{padding:.2rem .4rem}}.spinner-border{width:2rem;height:2rem}@media print{.card-header,.btn,.pagination,.form-control,.form-select{display:none!important}.card{box-shadow:none!important;border:1px solid #dee2e6!important}.table{font-size:.75rem}}@media (prefers-contrast: high){.sortable-table th.sortable.sorted{background-color:#000!important;color:#fff!important}.pagination .page-item.active .page-link{background-color:#000!important;border-color:#000!important}}@media (prefers-reduced-motion: reduce){.sortable-table th.sortable,.pagination .page-link,.btn{transition:none!important}}\n"]
    }]
  }],
